saved{font-size:12px;color:#18864b;margin-top:7px;min-height:15px}.saved.fail{color:#b42318;font-weight:700}.review-list{background:#fff7cc;border:2px solid #d6a500}.review-list button{margin:4px}.score{width:120px;font-size:22px;font-weight:800;text-align:center;padding:10px;border:2px solid #cdd3dc;border-radius:10px}.submitbar{position:sticky;bottom:0;background:rgba(244,246,249,.96);padding:14px 0}.submit{width:100%;border:0;background:#d10f32;color:#fff;padding:15px;border-radius:11px;font-size:17px;font-weight:800}.locked{background:#e8f6ed;border:1px solid #a9d8b9;border-radius:14px;padding:24px;text-align:center;font-weight:800}.small{font-size:12px;color:#667085;margin-top:8px}@media(max-width:620px){.choices{grid-template-columns:repeat(3,1fr);gap:9px}}
