g:16px 12px}.top h1{font-size:22px}.final-rank-card{padding:13px;margin-bottom:8px}.final-rank-card .bib{font-size:25px}.final-rank-head{margin-bottom:9px}.rank-toolbar{align-items:stretch;flex-direction:column}.rank-filter-button{width:100%}.rank-grid{gap:7px}.rank-button{min-height:46px;font-size:18px}.competitor-comment{margin-top:8px}.comment-rank-hint{display:block;margin-top:2px}}
